/* Rift Kontra · VALORANT — elle hazırlanmış lineup ve kurulumlar (update.js bu dosyaya dokunmaz)
 *
 * Açık bir lineup veri seti yok; bu liste elle yazılır. Yalnızca yaygın, standart kabul edilen
 * kurulumlar ve atışlar girilir. Konumlar BÖLGE düzeyindedir (valorant-api.com'un harita bölge adları):
 * "nerede durulur" ve "nereye atılır/kurulur" bölge adıyla verilir; piksel hassasiyetinde nişan noktası
 * uydurulmaz. Kesin nişan, şarj ve sekme ayarı için kayıtlar doğrulanmış bir YouTube videosuna, mümkünse
 * kaydın başladığı saniyeye bağlanır (video yoksa YouTube araması). Video bölümlerinden eklenen kayıtlar
 * listenin sonundadır; başlık ve hedef bölge videonun bölüm (chapter) başlığından alınmıştır.
 * Kontrol edilen sürüm: 13.10. Harita değişikliklerinden sonra ilgili harita gözden geçirilmeli.
 *
 * Yapı
 *  abil   "ajan:tuş" → en: İngilizce yetenek adı (video araması için), how: varsayılan "nasıl atılır/kurulur".
 *  list   Kayıtlar:
 *    ag    ajan kimliği (data/game.js), ab: yetenek tuşu (Q/E/C/X)
 *    map   harita kimliği, side: "atk" saldırı · "def" savunma
 *    type  "lineup" (atılır, nişan önemli) · "setup" (yerleştirilen kurulum) · "smoke" (haritadan konan duman)
 *    to    hedef bölge: haritadaki tıklanabilir nokta. Bölge anahtarı İngilizcedir ("B Main").
 *          "X~Y" iki bölgenin ortası (ör. bir kapı ya da geçiş), "X~Y@0.3" X'ten Y'ye %30.
 *    from  (isteğe bağlı) durulacak bölge; haritada daire ve hedefe çizgi olarak çizilir
 *    look  (isteğe bağlı) kurulumun baktığı/kapattığı bölge; kesikli çizgiyle çizilir
 *    title kısa başlık · stand: nerede dur · aim: nereye nişan al / nereye kur · how: (isteğe bağlı)
 *          varsayılan anlatıma eklenen not · does: ne işe yarar · yt: (isteğe bağlı) aramaya eklenecek
 *          İngilizce sözcükler · v: (isteğe bağlı) bu kaydı gösteren YouTube video kimliği (vids'te olmalı)
 *          · t: (isteğe bağlı) videoda kaydın başladığı saniye; videonun kendi bölüm zamanı, tahmin değil
 *          · im: (isteğe bağlı) YouTube'un o bölüm için ürettiği küçük resmin i.ytimg.com/vi/{v}/ sonrası
 *          yolu (izleme sayfasının herkese açık bölüm listesinden, imzalı; yüklenmezse video küçük resmi)
 *  vids   video kimliği → [başlık, kanal]; her kimlik youtube.com/oembed ile doğrulandı (gömülebilir)
 *  vid    "ajan:harita" → o ikili için genel video (kayda özel video yoksa ve kaydı olmayan haritada)
 */
